import {preferences} from './storage.js';
import {SoftWorld,EventBus,LEVELS,center} from './physics.js';
export class Game {
 constructor(){this.bus=new EventBus();this.world=new SoftWorld(this.bus);this.best=Number(preferences.getItem('cat-best')||0);this.reset()}
 reset(){this.world.wake();this.world.bodies=[];this.world.contacts.clear();this.world.time=0;this.score=0;this.merges=0;this.next=0;this.preview=1;this.cooldown=0;this.dropBlocked=false;this.over=false;this.paused=false;this.overflow=0;this.highest=0;this.bus.emit('Reset',{})}
 drop(x){this.dropBlocked=false;if(this.paused||this.over||this.world.time<this.cooldown)return false;const level=this.next,r=LEVELS[level].r,dropX=Math.max(this.world.left+r,Math.min(this.world.right-r,x));this.dropBlocked=!this.world.canSpawn(level,dropX,70);if(this.dropBlocked)return false;this.world.spawn(level,dropX,70);this.next=this.preview;this.preview=Math.random()<.6?0:Math.random()<.7?1:2;this.cooldown=this.world.time+.5;return true}
 update(dt){if(this.paused||this.over)return;const contacts=this.world.step(dt),used=new Set();for(const {a,b}of contacts){if(this.disableMerge)continue;if(a.level!==b.level||a.level>=LEVELS.length-1||used.has(a.id)||used.has(b.id)||this.world.time-a.born<.18||this.world.time-b.born<.18)continue;used.add(a.id);used.add(b.id);const c=center(a),d=center(b),m=a.mass+b.mass;let vx=0,vy=0;for(const p of a.p){vx+=p.vx*a.mass/a.p.length;vy+=p.vy*a.mass/a.p.length}for(const p of b.p){vx+=p.vx*b.mass/b.p.length;vy+=p.vy*b.mass/b.p.length}this.world.remove([a.id,b.id]);const level=a.level+1,newborn=this.world.spawn(level,(c.x*a.mass+d.x*b.mass)/m,Math.min(this.world.floor-LEVELS[level].r,(c.y*a.mass+d.y*b.mass)/m),vx/m,vy/m);this.score+=2**(level+1);this.merges++;this.highest=Math.max(this.highest,level);this.bus.emit('CatMerged',{sourceIds:[a.id,b.id],resultId:newborn.id,level,x:center(newborn).x,y:center(newborn).y,time:this.world.time})}
 const danger=this.world.bodies.some(b=>this.world.time-b.born>2.4&&b.p.some(p=>p.y<125)&&Math.abs(b.p.reduce((v,p)=>v+p.vy,0)/b.p.length)<60);this.overflow=danger?this.overflow+dt:Math.max(0,this.overflow-dt*2);if(this.overflow>3){this.over=true;this.bus.emit('GameOver',{})}if(this.score>this.best){this.best=this.score;preferences.setItem('cat-best',this.best)}}
 demo(){this.reset();const {left,right,floor}=this.world,mid=(left+right)/2,list=[[2,left+50,floor-50],[3,mid,floor-60],[2,right-50,floor-50],[1,left+85,floor-165],[4,mid+55,floor-190],[1,right-50,floor-165],[3,mid,floor-315]];for(const [l,x,y]of list)this.world.spawn(l,x,y);this.bus.emit('Demo',{})}
}
